// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 lockTime, uint256 gift) public {
        // 1. keep the fuzzed domain wide but admissible
        lockTime = bound(lockTime, 0, 365 days);
        gift = bound(gift, 1 wei, 1 ether);

        // 2. adversarial counterpart: the configured log echoes a gift of `gift`
        //    wei back into C on its first AddMessage (re-entrant party).
        EchoLog log = new EchoLog(gift);
        vm.deal(address(log), gift);
        c.SetLogFile(address(log));
        c.Initialized();

        // drive C through Put (fallback path not needed): Put must notify the log
        c.Put(lockTime);

        // 3. general rule: every Put interacts with the configured log, so the
        //    log's re-entrant donation lands on C and address(c).balance == gift.
        //    The mutant (SetLogFile never stores the log) never calls AddMessage,
        //    so no donation happens and C's balance stays 0.
        assertTrue(address(c).balance == gift);
    }
}

// minimal adversarial helper: log contract that, on the first AddMessage from C,
// re-enters C's payable fallback with a donation of `gift` wei.
contract EchoLog {
    bool done;
    uint256 gift;

    constructor(uint256 _gift) { gift = _gift; }

    function AddMessage(address, uint256, string calldata) external {
        if (!done) {
            done = true;
            (bool s,) = msg.sender.call{value: gift}("");
            require(s);
        }
    }
}
